# =============================================================================
# 04_GSEA.R
#
# TFM: Transcriptomic response of human induced neurons to ionizing radiation
#
# Purpose:
#   Preranked Gene Set Enrichment Analysis (GSEA) using the moderated
#   t-statistic generated by 03_differential_expression.R.
#
# Collections:
#   1. MSigDB Hallmark
#   2. Gene Ontology Biological Process (GO:BP)
#   3. KEGG Legacy
#
# Ranking:
#   Unique gene symbols ranked by moderated t-statistic.
#
# Interpretation:
#   Positive NES = enrichment towards IR
#   Negative NES = enrichment towards CTL
#
# Reproducibility environment validated during TFM reconstruction:
#   MSigDB: 2026.1.Hs
#   msigdbr: 26.1.1
#   fgsea: 1.38.0
# =============================================================================


# =============================================================================
# 1. REQUIRED PACKAGES
# =============================================================================

required <- c(
    "fgsea",
    "msigdbr",
    "ggplot2"
)

missing_packages <- required[
    !vapply(
        required,
        requireNamespace,
        logical(1),
        quietly = TRUE
    )
]

if (length(missing_packages) > 0L) {
    stop(
        "Install missing packages before running this script: ",
        paste(missing_packages, collapse = ", ")
    )
}

library(fgsea)
library(msigdbr)
library(ggplot2)


# =============================================================================
# 2. OUTPUT DIRECTORIES
# =============================================================================

dir.create(
    "results/GSEA",
    recursive = TRUE,
    showWarnings = FALSE
)

dir.create(
    "figures/GSEA",
    recursive = TRUE,
    showWarnings = FALSE
)


# =============================================================================
# 3. LOAD GSEA RANKING GENERATED BY 03_differential_expression.R
# =============================================================================

ranking_file <- "results/GSEA_ranked_genes.csv"

if (!file.exists(ranking_file)) {
    stop(
        "Cannot find ",
        ranking_file,
        ". Run 03_differential_expression.R first."
    )
}

ranking_df <- read.csv(
    ranking_file,
    stringsAsFactors = FALSE,
    check.names = FALSE
)

required_columns <- c(
    "gene_symbol",
    "t"
)

if (!all(required_columns %in% names(ranking_df))) {
    stop(
        "GSEA ranking must contain columns: ",
        paste(required_columns, collapse = ", ")
    )
}


# =============================================================================
# 4. BUILD GSEA RANKING
# =============================================================================

ranking_df <- ranking_df[
    !is.na(ranking_df$gene_symbol) &
    ranking_df$gene_symbol != "" &
    !is.na(ranking_df$t) &
    is.finite(ranking_df$t),
    ,
    drop = FALSE
]

# If duplicated symbols are present, retain the observation with the
# largest absolute moderated t-statistic.

ranking_df <- ranking_df[
    order(
        abs(ranking_df$t),
        decreasing = TRUE
    ),
    ,
    drop = FALSE
]

ranking_df <- ranking_df[
    !duplicated(ranking_df$gene_symbol),
    ,
    drop = FALSE
]

ranks <- ranking_df$t

names(ranks) <- ranking_df$gene_symbol

ranks <- sort(
    ranks,
    decreasing = TRUE
)

if (anyDuplicated(names(ranks))) {
    stop(
        "Duplicated gene symbols remain in the GSEA ranking."
    )
}

if (anyNA(ranks)) {
    stop(
        "NA values remain in the GSEA ranking."
    )
}

cat("\n")
cat("============================================================\n")
cat("GSEA INPUT\n")
cat("============================================================\n\n")

cat(
    "Genes in ranked list:",
    length(ranks),
    "\n"
)

cat(
    sprintf(
        "t-statistic range: %.3f to %.3f\n",
        min(ranks),
        max(ranks)
    )
)

if (length(ranks) != 17919L) {
    warning(
        "Expected 17,919 ranked genes, but found ",
        length(ranks),
        "."
    )
}


