# =============================================================================
# 7. BUILD PATHWAY LISTS
# =============================================================================

make_pathway_list <- function(msig_df) {

    if (!all(
        c(
            "gs_name",
            "gene_symbol"
        ) %in% names(msig_df)
    )) {
        stop(
            "MSigDB table does not contain gs_name and gene_symbol."
        )
    }

    pathways <- split(
        msig_df$gene_symbol,
        msig_df$gs_name
    )

    pathways <- lapply(
        pathways,
        function(x) {

            x <- x[
                !is.na(x) &
                x != ""
            ]

            unique(x)
        }
    )

    pathways
}


hallmark_pathways <- make_pathway_list(
    hallmark_msig
)

gobp_pathways <- make_pathway_list(
    gobp_msig
)

kegg_pathways <- make_pathway_list(
    kegg_msig
)


cat("\n")
cat("Available gene sets before GSEA filtering:\n")

cat(
    "  Hallmark:",
    length(hallmark_pathways),
    "\n"
)

cat(
    "  GO:BP:",
    length(gobp_pathways),
    "\n"
)

cat(
    "  KEGG Legacy:",
    length(kegg_pathways),
    "\n"
)


# =============================================================================
# 8. GSEA FUNCTION
# =============================================================================
#
# fgsea applies minSize and maxSize after matching pathway genes against
# the genes present in the ranked list.
#
# No additional manual size prefiltering is performed here.
# =============================================================================

run_gsea <- function(pathways, stats) {

    set.seed(123)

    result <- fgseaMultilevel(
        pathways = pathways,
        stats = stats,
        minSize = 15,
        maxSize = 500,
        eps = 0
    )

    result <- as.data.frame(result)

    result <- result[
        order(
            result$padj,
            -abs(result$NES)
        ),
        ,
        drop = FALSE
    ]

    result$direction <- ifelse(
        result$NES > 0,
        "IR",
        "CTL"
    )

    rownames(result) <- NULL

    result
}


# =============================================================================
# 9. RUN HALLMARK GSEA
# =============================================================================

cat("\n")
cat("============================================================\n")
cat("HALLMARK GSEA\n")
cat("============================================================\n\n")

hallmark_gsea <- run_gsea(
