# =============================================================================
# 12. SAFE CSV EXPORT FUNCTION
# =============================================================================
#
# fgsea returns leadingEdge as a list-column.
# write.csv() cannot write list-columns directly.
#
# Therefore, leadingEdge is converted to a semicolon-separated string
# only in the copy used for CSV export.
#
# The original GSEA objects retain the list-column for downstream analysis.
# =============================================================================

prepare_gsea_for_csv <- function(x) {

    out <- as.data.frame(x)

    if ("leadingEdge" %in% names(out)) {

        out$leadingEdge <- vapply(
            out$leadingEdge,
            function(z) {

                paste(
                    z,
                    collapse = ";"
                )
            },
            character(1)
        )
    }

    out
}


