# =============================================================================
# 16. LEADING-EDGE OVERLAP
# =============================================================================

get_leading_edge <- function(pathway_name) {

    idx <- which(
        hallmark_interest$pathway ==
            pathway_name
    )

    if (length(idx) != 1L) {
        return(character(0))
    }

    hallmark_interest$leadingEdge[[idx]]
}


p53_le <- get_leading_edge(
    "HALLMARK_P53_PATHWAY"
)

dna_repair_le <- get_leading_edge(
    "HALLMARK_DNA_REPAIR"
)

apoptosis_le <- get_leading_edge(
    "HALLMARK_APOPTOSIS"
)

tnfa_le <- get_leading_edge(
    "HALLMARK_TNFA_SIGNALING_VIA_NFKB"
)


leading_edge_overlap <- data.frame(

    comparison = c(
        "P53 vs DNA repair",
        "P53 vs apoptosis",
        "P53 vs TNFA/NFKB"
    ),

    shared_genes_n = c(
        length(
            intersect(
                p53_le,
                dna_repair_le
            )
        ),

        length(
            intersect(
                p53_le,
                apoptosis_le
            )
        ),

        length(
            intersect(
                p53_le,
                tnfa_le
            )
        )
    ),

    shared_genes = c(

        paste(
