# 20B. INTEGRATED FUNCTIONAL PROFILE: HALLMARK + GO + KEGG
# =============================================================================
# Final TFM selection. Colour represents enrichment direction, shape represents
# gene-set collection, and point size represents -log10(FDR).

integrated_hallmark <- c(
    HALLMARK_P53_PATHWAY =
        "Vía de p53",
    HALLMARK_TNFA_SIGNALING_VIA_NFKB =
        "TNFα vía NF-κB",
    HALLMARK_DNA_REPAIR =
        "Reparación del ADN"
)

integrated_go <- c(
    GOBP_OXIDATIVE_PHOSPHORYLATION =
        "Fosforilación oxidativa",
    GOBP_INTRINSIC_APOPTOTIC_SIGNALING_PATHWAY_BY_P53_CLASS_MEDIATOR =
        "Apoptosis intrínseca mediada por p53",
    GOBP_RESPONSE_TO_OXIDATIVE_STRESS =
        "Respuesta al estrés oxidativo",
    GOBP_DENDRITE_DEVELOPMENT =
        "Desarrollo de dendritas",
    GOBP_REGULATION_OF_TRANS_SYNAPTIC_SIGNALING =
        "Regulación de la señalización transináptica"
)

integrated_kegg <- c(
    KEGG_GLUTATHIONE_METABOLISM =
        "Metabolismo del glutatión",
    KEGG_CYTOKINE_CYTOKINE_RECEPTOR_INTERACTION =
        "Interacción citocina-receptor",
    KEGG_LONG_TERM_POTENTIATION =
        "Potenciación a largo plazo",
    KEGG_AXON_GUIDANCE =
        "Guía axonal"
)

make_integrated_df <- function(
    gsea_table,
    pathways,
    collection
) {

    out <- gsea_table[
        gsea_table$pathway %in% names(pathways),
        c("pathway", "NES", "padj"),
        drop = FALSE
    ]

    data.frame(
        Proceso = unname(pathways[out$pathway]),
        NES = out$NES,
        FDR = out$padj,
        Coleccion = collection,
        stringsAsFactors = FALSE
    )
}

integrated_hallmark_df <- make_integrated_df(
    hallmark_gsea,
    integrated_hallmark,
    "Hallmark"
)

integrated_go_df <- make_integrated_df(
    gobp_gsea,
    integrated_go,
    "GO"
)

integrated_kegg_df <- make_integrated_df(
    kegg_gsea,
    integrated_kegg,
    "KEGG"
)

funcional <- rbind(
    integrated_hallmark_df,
    integrated_go_df,
    integrated_kegg_df
)

funcional$Direccion <- ifelse(
    funcional$NES > 0,
    "Enriquecida hacia IR",
    "Enriquecida hacia CTL"
)

funcional$Significancia <- -log10(funcional$FDR)

funcional$Proceso <- factor(
    funcional$Proceso,
    levels = funcional$Proceso[order(funcional$NES)]
)

p_integrated <- ggplot(
    funcional,
    aes(
        x = NES,
        y = Proceso,
        color = Direccion,
        shape = Coleccion,
        size = Significancia
    )
) +
    geom_point(alpha = 0.9) +
    geom_vline(
        xintercept = 0,
        linetype = "dashed",
        linewidth = 0.4
    ) +
    scale_color_manual(
        values = c(
            "Enriquecida hacia CTL" = "#F8766D",
            "Enriquecida hacia IR" = "#00BFC4"
        )
    ) +
    scale_shape_manual(
        values = c(
            Hallmark = 17,
            GO = 16,
            KEGG = 15
        )
    ) +
    labs(
        title = "Perfil funcional integrado de la respuesta a IR",
        subtitle = "Hallmark, GO y KEGG en neuronas inducidas a 336 h",
        x = "NES",
        y = NULL,
        color = "Dirección",
        shape = "Colección",
        size = expression(-log[10](FDR))
    ) +
    theme_classic(base_size = 12) +
    theme(
        plot.title = element_text(face = "bold"),
        legend.position = "right"
    )

ggsave(
    "figures/GSEA/integrated_functional_profile.pdf",
    p_integrated,
    width = 12,
    height = 5.5
)

ggsave(
